package integrity

import "testing"

const goGenHeader = "// Code generated by protoc-gen-go. DO NOT EDIT.\n"

// TestGeneratedHandEdits_InputsUnchanged is CV-11's own anchor: a changed
// generated file whose same-directory generator input (a .proto file) did
// NOT change in the range is a hand-edit finding.
func TestGeneratedHandEdits_InputsUnchanged(t *testing.T) {
	base := map[string][]byte{
		"api/thing.pb.go": []byte(goGenHeader + "package api\n\nvar Old = 1\n"),
		"api/thing.proto": []byte("syntax = \"proto3\";\nmessage Thing {}\n"),
	}
	head := map[string][]byte{
		"api/thing.pb.go": []byte(goGenHeader + "package api\n\nvar Old = 2 // hand-edited, never regenerated\n"),
		"api/thing.proto": []byte("syntax = \"proto3\";\nmessage Thing {}\n"), // unchanged
	}
	in := GeneratedInput{
		ChangedFiles: []string{"api/thing.pb.go"},
		BaseFile:     fileReader(base),
		HeadFile:     fileReader(head),
		SiblingFiles: map[string][]string{
			"api": {"api/thing.pb.go", "api/thing.proto"},
		},
	}
	findings, missing := GeneratedHandEdits(in)
	if len(missing) != 0 {
		t.Fatalf("missing = %v, want none", missing)
	}
	if len(findings) != 1 {
		t.Fatalf("got %d findings, want 1: %+v", len(findings), findings)
	}
	if findings[0].Kind != KindHandEdit || findings[0].Key != "api/thing.pb.go" {
		t.Errorf("got %+v, want hand_edit on api/thing.pb.go", findings[0])
	}
}

// TestGeneratedHandEdits_InputChangedIsClean: when the .proto input ALSO
// changed, regenerating explains the diff — no finding.
func TestGeneratedHandEdits_InputChangedIsClean(t *testing.T) {
	base := map[string][]byte{
		"api/thing.pb.go": []byte(goGenHeader + "package api\n\nvar Old = 1\n"),
		"api/thing.proto": []byte("message Thing {}\n"),
	}
	head := map[string][]byte{
		"api/thing.pb.go": []byte(goGenHeader + "package api\n\nvar Old = 2\n"),
		"api/thing.proto": []byte("message Thing { string name = 1; }\n"),
	}
	in := GeneratedInput{
		ChangedFiles: []string{"api/thing.pb.go"},
		BaseFile:     fileReader(base),
		HeadFile:     fileReader(head),
		SiblingFiles: map[string][]string{"api": {"api/thing.pb.go", "api/thing.proto"}},
	}
	findings, missing := GeneratedHandEdits(in)
	if len(findings) != 0 || len(missing) != 0 {
		t.Errorf("got findings=%+v missing=%v, want both empty", findings, missing)
	}
}

// TestGeneratedHandEdits_NonGeneratedFileIsIgnored: an ordinary changed Go
// file (no "Code generated … DO NOT EDIT" marker) is never flagged.
func TestGeneratedHandEdits_NonGeneratedFileIsIgnored(t *testing.T) {
	base := map[string][]byte{"pkg/plain.go": []byte("package pkg\n\nvar X = 1\n")}
	head := map[string][]byte{"pkg/plain.go": []byte("package pkg\n\nvar X = 2\n")}
	in := GeneratedInput{
		ChangedFiles: []string{"pkg/plain.go"},
		BaseFile:     fileReader(base),
		HeadFile:     fileReader(head),
		SiblingFiles: map[string][]string{"pkg": {"pkg/plain.go"}},
	}
	findings, missing := GeneratedHandEdits(in)
	if len(findings) != 0 || len(missing) != 0 {
		t.Errorf("got findings=%+v missing=%v, want both empty", findings, missing)
	}
}

// TestGeneratedHandEdits_UnlistableDirectoryIsMissing: a directory the
// caller could not list is named in Missing, never silently skipped or
// falsely flagged (I44).
func TestGeneratedHandEdits_UnlistableDirectoryIsMissing(t *testing.T) {
	base := map[string][]byte{"api/thing.pb.go": []byte(goGenHeader + "package api\n\nvar Old = 1\n")}
	head := map[string][]byte{"api/thing.pb.go": []byte(goGenHeader + "package api\n\nvar Old = 2\n")}
	in := GeneratedInput{
		ChangedFiles: []string{"api/thing.pb.go"},
		BaseFile:     fileReader(base),
		HeadFile:     fileReader(head),
		SiblingFiles: nil, // "api" was never listed
	}
	findings, missing := GeneratedHandEdits(in)
	if len(findings) != 0 {
		t.Errorf("got findings %+v, want none (never fabricated without a listing)", findings)
	}
	if len(missing) != 1 {
		t.Fatalf("got missing=%v, want exactly one entry", missing)
	}
}

// TestGeneratedHandEdits_NewlyAddedGeneratedFileIsClean: a generated file
// with no base content at all (newly added) is never a hand edit — there
// is nothing to compare against.
func TestGeneratedHandEdits_NewlyAddedGeneratedFileIsClean(t *testing.T) {
	head := map[string][]byte{"api/new.pb.go": []byte(goGenHeader + "package api\n")}
	in := GeneratedInput{
		ChangedFiles: []string{"api/new.pb.go"},
		BaseFile:     fileReader(map[string][]byte{}),
		HeadFile:     fileReader(head),
		SiblingFiles: map[string][]string{"api": {"api/new.pb.go"}},
	}
	findings, missing := GeneratedHandEdits(in)
	if len(findings) != 0 || len(missing) != 0 {
		t.Errorf("got findings=%+v missing=%v, want both empty", findings, missing)
	}
}
